# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HZ. EBU BEKİR\'İN (R.A.) KİMLİĞİ, İMANI VE SIDDIK UNVANI (PH.10.2.1)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">SOYU, KİMLİĞİ VE CAHİLİYE DÖNEMİ</text>\n  <text x="32" y="88" font-size="10.6" fill="#1e3a8a">• Asıl adı: Abdullah b. Ebû Kuhâfe Osman (Teym kolu)</text>\n  <text x="32" y="108" font-size="10.6" fill="#1e3a8a">• Hz. Peygamber\'den yaklaşık 2-3 yaş küçüktür (d. 573).</text>\n  <text x="32" y="128" font-size="10.6" fill="#1e3a8a">• Cahiliye döneminde bile puta tapmamış, içki içmemiş,</text>\n  <text x="32" y="146" font-size="10.6" fill="#1e3a8a">  iffeti ve dürüst kumaş ticaretiyle tanınmıştır.</text>\n  <text x="32" y="168" font-size="10.6" font-weight="bold" fill="#1d4ed8">• Ensâb (Arap soy bilimi) ve hitabet ilminde uzmandır.</text>\n  <text x="32" y="188" font-size="10.6" fill="#1e3a8a">• Lakapları: es-Sıddîk, el-Atîk, Sâhibü\'l-Gâr (Mağara dostu).</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">İLK İMAN VE DAVET HALKASI</text>\n  <text x="372" y="88" font-size="10.6" fill="#14532d">• Hür yetişkin erkekler arasında ilk Müslümandır.</text>\n  <text x="372" y="108" font-size="10.6" fill="#14532d">• Peygamberimiz onun tereddütsüz imanını övmüştür.</text>\n  <text x="372" y="128" font-size="10.6" font-weight="bold" fill="#15803d">• Onun davetiyle İslam\'a giren büyük sahâbîler:</text>\n  <text x="380" y="146" font-size="10.4" fill="#14532d">- Hz. Osman b. Affân, Hz. Zübeyr b. Avvâm</text>\n  <text x="380" y="164" font-size="10.4" fill="#14532d">- Hz. Talha b. Ubeydullah, Hz. Sa\'d b. Ebî Vakkâs</text>\n  <text x="380" y="182" font-size="10.4" fill="#14532d">- Hz. Abdurrahman b. Avf, Hz. Ebû Ubeyde b. Cerrâh</text>\n  <text x="372" y="200" font-size="10.3" font-weight="bold" fill="#166534">• İsra ve Miraç mucizesini tereddütsüz tasdik → «es-Sıddîk»</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Hz. Ebu Bekir; iman, sadakat, tebliğ gayreti ve vefasıyla Peygamberimizin en yakın dostu olmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HİCRET YOLDAŞLIĞI (SEVR MAĞARASI) VE İNFAK AHLAKI</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">HİCRET YOLDAŞLIĞI VE SEVR MAĞARASI</text>\n  <text x="32" y="88" font-size="10.6" fill="#78350f">• Tevbe suresi 40. ayette «İkinin ikincisi (Sâniye\'s-neyn)»</text>\n  <text x="32" y="106" font-size="10.6" fill="#78350f">  ve «Üzülme, Allah bizimle beraberdir» müjdesinin muhatabı.</text>\n  <text x="32" y="126" font-size="10.6" fill="#78350f">• İki deve hazırlamış, yol rehberi tutmuş, Sevr Mağarası\'nda</text>\n  <text x="32" y="144" font-size="10.6" fill="#78350f">  Peygamberimizi korumak için kendi canını siper etmiştir.</text>\n  <text x="32" y="164" font-size="10.6" fill="#78350f">• Çocukları Esma (Zâtü\'n-Nitâkayn) ve Abdullah ile</text>\n  <text x="32" y="182" font-size="10.6" fill="#78350f">  azatlısı Âmir b. Füheyre hicret planında görev almıştır.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">İNFAK AHLAKI VE KÖLELERİ AZAT ETMESİ</text>\n  <text x="372" y="88" font-size="10.6" fill="#581c87">• Mekke\'de işkence gören Bilâl-i Habeşî, Âmir b. Füheyre,</text>\n  <text x="372" y="106" font-size="10.6" fill="#581c87">  Zinnîre, Ümmü Ubeys ve Nehdiyye gibi mazlum köleleri</text>\n  <text x="372" y="124" font-size="10.6" font-weight="bold" fill="#6b21a8">  servetiyle satın alıp Allah rızası için hürriyetine kavuşturdu.</text>\n  <text x="372" y="146" font-size="10.6" fill="#581c87">• Mescid-i Nebevî\'nin arsasının bedelini ödedi.</text>\n  <text x="372" y="166" font-size="10.6" fill="#581c87">• Tebük Seferi\'nde malının tamamını İslam ordusuna bağışladı;</text>\n  <text x="372" y="184" font-size="10.6" font-weight="bold" fill="#6b21a8">  «Ailene ne bıraktın?» sorusuna: «Allah ve Resulünü!» dedi.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Leyl suresi 17-21. ayetler, malını sırf Allah rızası için infak eden Hz. Ebu Bekir hakkında nazil olmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MEDİNE YILLARI, VEFAT HABERİ KARŞISINDAKİ METANETİ VE HALİFELİĞİ</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">MEDİNE DÖNEMİ VE SÜNNETE BAĞLILIĞI</text>\n  <text x="32" y="88" font-size="10.6" fill="#064e3b">• Bedir, Uhud, Hendek, Hudeybiye, Hayber, Mekke\'nin Fethi,</text>\n  <text x="32" y="106" font-size="10.6" fill="#064e3b">  Huneyn ve Tebük başta olmak üzere tüm gazvelere katıldı.</text>\n  <text x="32" y="126" font-size="10.6" fill="#064e3b">• Hicri 9. yılda ilk İslam Hac kafilesine «Hac Emîri» oldu.</text>\n  <text x="32" y="146" font-size="10.6" fill="#064e3b">• Hz. Peygamber\'in son hastalığında Mescid-i Nebevî\'de</text>\n  <text x="32" y="164" font-size="10.6" font-weight="bold" fill="#047857">  17 vakit namazda ashab-ı kirama imamlık yaptı.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">METANETİ VE HALİFELİK HİZMETLERİ (632-634)</text>\n  <text x="372" y="88" font-size="10.6" fill="#7c2d12">• Hz. Peygamber\'in vefatı üzerine şaşkınlığa düşen sahâbeyi</text>\n  <text x="372" y="106" font-size="10.6" fill="#7c2d12">  Âl-i İmrân 144. ayeti okuyarak teskin etti.</text>\n  <text x="372" y="126" font-size="10.6" fill="#7c2d12">• Üsâme b. Zeyd ordusunu göndererek sünneti korudu.</text>\n  <text x="372" y="146" font-size="10.6" fill="#7c2d12">• Ridde ve yalancı peygamber isyanlarını bastırıp birliği sağladı.</text>\n  <text x="372" y="166" font-size="10.6" font-weight="bold" fill="#9a3412">• Kur\'an-ı Kerim ayetlerini «Mushaf» hâline cem ettirdi.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Hz. Ebu Bekir (r.a.), Hicri 13 (M. 634) yılında 63 yaşında vefat etmiş ve Hücre-i Saâdet\'e defnedilmiştir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
